function Kresba({
  viewBox,
  svg,
  className,
}: {
  viewBox: string;
  svg: string;
  className?: string;
}) {
  return (
    <svg
      className={className}
      viewBox={viewBox}
      aria-hidden="true"
      dangerouslySetInnerHTML={{ __html: svg }}
    />
  );
}

/** 03 — samostatný symbol (favicon, profilovka, drobné plochy) */
export function AquaFishMark({ className }: { className?: string }) {
  return <Kresba viewBox={VB_SYMBOL} svg={SVG_SYMBOL} className={className} />;
}

/** 02 — zostava bez taglineu; navigácia a menšie plochy */
export function Logo({ className }: { className?: string }) {
  return (
    <Kresba
      viewBox={VB_LOGO}
      svg={SVG_LOGO}
      className={`logo${className ? " " + className : ""}`}
    />
  );
}

/** 01 — zostava s taglineom; pätička a titulné plochy */
export function LogoPlny({ className }: { className?: string }) {
  return (
    <Kresba
      viewBox={VB_TAGLINE}
      svg={SVG_TAGLINE}
      className={`logo logo--plny${className ? " " + className : ""}`}
    />
  );
}

