export function LogoV1({ className, tag = true }: { className?: string; tag?: boolean }) {
  return (
    <svg
      className={`logo${className ? " " + className : ""}`}
      viewBox={V1_VB}
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
    >
      <path fillRule="evenodd" d={tag ? V1_S_TAGOM : V1_BEZ_TAGU} />
    </svg>
  );
}

